/**
 * @id data-table-basic
 * @title Basic Data Table
 * @apiId @skyra/ui::DataTable
 * @packageId @skyra-tech-platform/data-table
 */
import React from 'react';
import '@skyra-tech-platform/data-table';;

export default function DataTableBasicExample() {
  const data = [
    { id: '1', name: 'Alice Smith', role: 'Admin', status: 'Active' },
    { id: '2', name: 'Bob Jones', role: 'Editor', status: 'Inactive' },
    { id: '3', name: 'Charlie Brown', role: 'Viewer', status: 'Active' },
  ];

  const columns: any[] = [
    { key: 'name', accessor: 'name', header: 'Name' },
    { key: 'role', accessor: 'role', header: 'Role' },
    { key: 'status', accessor: 'status', header: 'Status' },
  ];

  return (
    <div style={{ border: '1px solid var(--skyra-border)', borderRadius: 'var(--skyra-radius-md)', overflow: 'hidden' }}>
      <skyra-tech-data-table 
        data={data} 
        columns={columns} 
      />
    </div>
  );
}

/**
 * @id dialogs-confirm-basic
 * @title Confirm Dialog
 * @apiId @skyra/dialogs::ConfirmDialog
 * @packageId @skyra/dialogs
 */
import React, { useState, useRef, useEffect } from 'react';
import '@skyra-tech-platform/button';;
import { Trash2 } from 'lucide-react';
import '@skyra-tech-platform/dialog';

export default function ConfirmDialogExample() {
  const [open, setOpen] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const ref = useRef<any>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const handleClose = () => setOpen(false);
    el.addEventListener('skyra-close', handleClose);
    el.addEventListener('skyra-cancel', handleClose);

    return () => {
      el.removeEventListener('skyra-close', handleClose);
      el.removeEventListener('skyra-cancel', handleClose);
    };
  }, []);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', alignItems: 'flex-start' }}>
      <skyra-tech-button variant="danger" onClick={() => setOpen(true)}>Open Confirm Dialog</skyra-tech-button>
      
      {result && (
        <div style={{ fontSize: '0.875rem', color: 'var(--skyra-text-muted)' }}>
          Last action: <strong>{result}</strong>
        </div>
      )}

      <skyra-tech-dialog ref={ref} open={open || undefined} mode="modal" hide-close-button>
        <div style={{ padding: '0.5rem', display: 'flex', flexDirection: 'column' }}>
          <div style={{
            width: '48px', height: '48px', borderRadius: 'var(--skyra-radius-lg)',
            background: 'var(--skyra-danger-light)', display: 'flex', alignItems: 'center',
            justifyContent: 'center', marginBottom: '1.25rem', color: 'var(--skyra-danger)',
          }}>
            <Trash2 size={22} />
          </div>
          <h2 style={{ fontFamily: 'var(--skyra-font-display)', fontWeight: 700, fontSize: '1.125rem', color: 'var(--skyra-text)', margin: '0 0 0.625rem' }}>
            Delete Item
          </h2>
          <div style={{ fontSize: '0.9rem', color: 'var(--skyra-text-muted)', lineHeight: 1.6, marginBottom: '1.75rem' }}>
            Are you sure you want to delete this item? This action cannot be undone.
          </div>
          <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end', flexWrap: 'wrap' }}>
            <skyra-tech-button variant="ghost" onClick={() => {
              setResult('Cancelled');
              setOpen(false);
            }}>Cancel</skyra-tech-button>
            <skyra-tech-button variant="danger" onClick={() => {
              setResult('Confirmed delete');
              setOpen(false);
            }}>Delete</skyra-tech-button>
          </div>
        </div>
      </skyra-tech-dialog>
    </div>
  );
}

/**
 * @id dynamic-form-basic
 * @title Basic Dynamic Form
 * @apiId @skyra/ui::DynamicForm
 * @packageId @skyra-tech-platform/dynamic-form
 */
import React from 'react';
import '@skyra-tech-platform/dynamic-form';;

export default function DynamicFormBasicExample() {
  const fields = [
    { id: 'firstName', type: 'text' as const, label: 'First Name', required: true },
    { id: 'lastName', type: 'text' as const, label: 'Last Name' },
    { id: 'email', type: 'text' as const, label: 'Email', required: true }
  ];

  return (
    <div style={{ maxWidth: '400px' }}>
      <skyra-tech-dynamic-form 
        ref={(el: HTMLElement | null) => {
          if (el) {
            (el as any).fields = fields;
            el.addEventListener("skyra-submit", (e: Event) => alert(JSON.stringify((e as CustomEvent).detail.values, null, 2)));
          }
        }}
      />
    </div>
  );
}

/**
 * @id qr-core-basic
 * @title Core QR Generation
 * @apiId @skyra-tech-platform/qr::generateQRCode
 * @packageId @skyra-tech-platform/qr
 * @capabilityId qr/core
 */
import { generateQRCode } from '@skyra-tech-platform/qr';

export function runExample() {
  // Runtime neutral QR code generation
  // Can be executed on Node.js, edge, or browser
  return generateQRCode('https://skyra.com', {
    errorCorrectionLevel: 'H',
    version: 4
  });
}

/**
 * @id qr-react-basic
 * @title React QR Code
 * @apiId @skyra/ui::QRCode
 * @packageId @skyra/ui
 * @capabilityId ui/components
 */
import React from 'react';
import '@skyra-tech-platform/qr';;

export default function QRReactExample() {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', alignItems: 'center' }}>
      <p>Scan to visit Skyra Platform:</p>
      <skyra-tech-qr-code 
        value="https://skyra.com" 
        width={200}
      />
    </div>
  );
}

﻿/**
 * @id utils-date-format
 * @title Date Formatting
 * @apiId @skyra-tech-platform/utils::formatDate
 * @packageId @skyra-tech-platform/utils
 */
import { formatDate } from '@skyra-tech-platform/utils';

export function runExample() {
  // Runtime-neutral utility function for standardizing dates
  const input = '2026-09-27T10:00:00Z';
  const result = formatDate(input, { format: 'short' });
  console.log(`Formatted: ${result}`);
  return result;
}
